import { type AttachmentHandlerOpts, type WebAttachmentDeclaration } from "@sierra/web";
import { createRoot, type Root } from "react-dom/client";

declare global {
    // eslint-disable-next-line no-var
    var sierraImageProxyURL: (url: string) => string;
}

/**
 * `rewriteImageUrl` rewrites the input URL if the global `sierraImageProxyURL`
 * variable is defined.
 *
 * @param url - The image URL to be rewritten
 */
export function rewriteImageUrl(url: string): string {
    return typeof globalThis.sierraImageProxyURL !== "undefined" ? sierraImageProxyURL(url) : url;
}

const rootElements = new Map<HTMLElement, Root>();

/**
 * Memoized container react roots and renders the element inside.
 */
export function memoRenderRoot(container: HTMLElement, element: React.ReactNode) {
    let reactRoot = rootElements.get(container);
    if (!reactRoot) {
        reactRoot = createRoot(container);
        rootElements.set(container, reactRoot);
    }
    reactRoot.render(element);
}

/**
 * Safely parses a JSON string into a typed object. Catches a parse exception and returns undefined.
 */
export function safeJSONParse<T>(data: string | undefined): T | undefined {
    if (!data) {
        return undefined;
    }
    try {
        return JSON.parse(data) as T;
    } catch {
        return undefined;
    }
}

/**
 * Creates a mock attachment handler options object to be used when rendering a preview of an
 * attachment.
 */
export function mockAttachmentOpts(): AttachmentHandlerOpts {
    return {
        containerElement: document.createElement("div"),
        isLastMessage: true,
        sendMessage: () => {},
        setChatInputHidden: () => {},
        refreshSecret: () => Promise.resolve(true),
        canSendMessage: true,
        nextHandler: null,
        store: {
            get: () => undefined,
            set: () => {},
        },
    };
}

export type ReactWebAttachmentDeclaration<T extends object> = WebAttachmentDeclaration & {
    render: (data: T, opts: AttachmentHandlerOpts) => React.ReactNode;
};

/**
 * Creates a web attachment declaration that memoizes the react node rendered in the container
 * element.
 */
export function reactDeclaration<T extends object>(
    decl: Omit<WebAttachmentDeclaration, "renderPreview"> & {
        renderPreview: (data: T | undefined) => React.ReactNode;
        render: (data: T, opts: AttachmentHandlerOpts) => React.ReactNode;
    }
): ReactWebAttachmentDeclaration<T> {
    return {
        ...decl,
        renderPreview: (containerElement, data) => {
            const props = safeJSONParse<T>(data);
            const reactNode = decl.renderPreview(props);
            memoRenderRoot(containerElement, reactNode);
        },
    };
}
